import{_ as o,o as i,c as a,a5 as n}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Service Boundaries — BrandHub V2","description":"","frontmatter":{},"headers":[],"relativePath":"service-boundaries.md","filePath":"service-boundaries.md"}'),s={name:"service-boundaries.md"};function c(r,e,t,l,h,d){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="service-boundaries-—-brandhub-v2" tabindex="-1">Service Boundaries — BrandHub V2 <a class="header-anchor" href="#service-boundaries-—-brandhub-v2" aria-label="Permalink to &quot;Service Boundaries — BrandHub V2&quot;">​</a></h1><p>&gt; DA-1153 (DA-E05-02). Nguồn: <code>docs/database/schema-v2/brandhub-dbml.dbml</code> (header comment — ownership chuẩn), <code>docs/ba/00-overview.md</code>. &gt; Mô hình nghiệp vụ V2: <code>Agency → Workspace → Media Package → Media Campaign → Task</code>. Không còn Workspace phẳng như V1.</p><h2 id="_1-business-service-java-spring-boot-3-port-8081" tabindex="-1">1. business-service (Java Spring Boot 3, port 8081) <a class="header-anchor" href="#_1-business-service-java-spring-boot-3-port-8081" aria-label="Permalink to &quot;1. business-service (Java Spring Boot 3, port 8081)&quot;">​</a></h2><h3 id="owns" tabindex="-1">Owns <a class="header-anchor" href="#owns" aria-label="Permalink to &quot;Owns&quot;">​</a></h3><ul><li><strong>PostgreSQL — toàn bộ 23 bảng</strong> (identity, organization, commerce, collaborator, billing): <ul><li>Identity: <code>users</code>, <code>user_oauth_providers</code>, <code>user_refresh_tokens</code>, <code>user_system_roles</code></li><li>Organization: <code>agencies</code>, <code>agency_members</code>, <code>agency_invitations</code>, <code>workspaces</code>, <code>workspace_members</code>, <code>workspace_invitations</code>, <code>workspace_templates</code>, <code>client_profiles</code></li><li>Commerce: <code>media_packages</code>, <code>workspace_media_packages</code>, <code>media_campaigns</code></li><li>Collaborator: <code>third_party_collaborators</code>, <code>campaign_collaborators</code></li><li>Billing: <code>subscription_plans</code>, <code>user_subscriptions</code>, <code>transactions</code>, <code>ai_credit_ledgers</code>, <code>ai_credit_creator_limits</code>, <code>audit_logs</code></li></ul></li><li><strong>MongoDB — 14 collections</strong> (business domain, không phải AI/publish log): <code>tasks</code>, <code>task_approvals</code>, <code>posts</code>, <code>content_requests</code>, <code>material_repository</code>, <code>brand_collections</code>, <code>hashtag_collections</code>, <code>content_versions</code>, <code>livestream_sessions</code>, <code>survey_forms</code>, <code>survey_responses</code>, <code>mail_templates</code>, <code>social_accounts</code>, <code>notifications</code></li><li><strong>Redis</strong> — JWT blacklist, rate limit, session cache.</li><li>Toàn bộ RBAC (<code>RequireRoleAspect</code>): <code>SystemRole</code> (ADMIN/USER) + <code>MemberRole</code> (MANAGER/CREATOR/CLIENT theo Workspace) + Agency-level owner check.</li></ul><h3 id="does-not-own" tabindex="-1">Does NOT own <a class="header-anchor" href="#does-not-own" aria-label="Permalink to &quot;Does NOT own&quot;">​</a></h3><ul><li>Không gọi trực tiếp Social Platform API (Facebook/Instagram/TikTok/Threads) — publisher-service làm việc đó.</li><li>Không sinh nội dung AI (caption/image/video/ambassador) — chỉ gọi REST tới ai-service, không tự implement logic AI.</li><li>Không kết nối ChromaDB hoặc AWS S3 (media gen output) — ai-service sở hữu.</li></ul><h3 id="trach-nhiem-nghiep-vu-chinh-v2" tabindex="-1">Trách nhiệm nghiệp vụ chính (V2) <a class="header-anchor" href="#trach-nhiem-nghiep-vu-chinh-v2" aria-label="Permalink to &quot;Trách nhiệm nghiệp vụ chính (V2)&quot;">​</a></h3><ul><li>Toàn bộ vòng đời Agency → Workspace → Media Package → Media Campaign → Task backlog → Task Approval Sequence (Creator → [QC] → Manager → Client).</li><li>Đẩy Task lên RabbitMQ cho publisher-service khi Post-type task hoàn tất Approval Sequence và tới lịch đăng.</li><li>Là &quot;orchestrator&quot; duy nhất — publisher-service KHÔNG BAO GIỜ gọi Social API trực tiếp mà không qua message từ business-service.</li></ul><hr><h2 id="_2-ai-service-python-fastapi-port-8082" tabindex="-1">2. ai-service (Python FastAPI, port 8082) <a class="header-anchor" href="#_2-ai-service-python-fastapi-port-8082" aria-label="Permalink to &quot;2. ai-service (Python FastAPI, port 8082)&quot;">​</a></h2><h3 id="owns-1" tabindex="-1">Owns <a class="header-anchor" href="#owns-1" aria-label="Permalink to &quot;Owns&quot;">​</a></h3><ul><li><strong>ChromaDB</strong> — brand knowledge vectors, RAG embeddings (collection naming: <code>agency_{agencyId}_brand_voice</code>, xem §DA-1158 khi hoàn tất — thay cho <code>workspace_{workspaceId}</code> cũ vì AI credit/brand voice giờ gắn cấp Agency, không phải Workspace lẻ).</li><li><strong>AWS S3</strong> — media output do AI generate (ảnh/video từ UC-77, UC-78).</li><li><strong>MongoDB — 2 collections</strong>: <code>knowledge_documents</code> (RAG source), <code>ai_usage_logs</code> (tracking credit usage per generation — nguồn cho FR 3.9.5 View AI Credit Tracking, dù bảng credit balance chính nằm ở PostgreSQL <code>ai_credit_ledgers</code> phía business-service).</li></ul><h3 id="does-not-own-1" tabindex="-1">Does NOT own <a class="header-anchor" href="#does-not-own-1" aria-label="Permalink to &quot;Does NOT own&quot;">​</a></h3><ul><li>Không kết nối MongoDB business collections (<code>tasks</code>, <code>posts</code>...) hay PostgreSQL — lấy business context (Workspace/Campaign/brand info) qua REST API từ business-service khi cần.</li><li>Không quản lý AI credit balance/limit (đó là PostgreSQL <code>ai_credit_ledgers</code>/<code>ai_credit_creator_limits</code>, business-service sở hữu) — ai-service chỉ ghi log usage, business-service là nguồn sự thật cho số dư.</li></ul><h3 id="trach-nhiem-nghiep-vu-chinh-v2-1" tabindex="-1">Trách nhiệm nghiệp vụ chính (V2) <a class="header-anchor" href="#trach-nhiem-nghiep-vu-chinh-v2-1" aria-label="Permalink to &quot;Trách nhiệm nghiệp vụ chính (V2)&quot;">​</a></h3><ul><li>Generate: Caption, AI Brand Ambassador, Image, Video, Livestream Script (UC-74 → UC-82).</li><li>Trend crawl (ADMIN-configured, FR 3.7.9) + hashtag/trending topic suggestion.</li><li>Recommend Media Collaborator (UC-82) — chỉ gợi ý, không tự liên hệ/ký kết.</li></ul><hr><h2 id="_3-publisher-service-java-spring-boot-3-stateless-port-8083" tabindex="-1">3. publisher-service (Java Spring Boot 3, stateless, port 8083) <a class="header-anchor" href="#_3-publisher-service-java-spring-boot-3-stateless-port-8083" aria-label="Permalink to &quot;3. publisher-service (Java Spring Boot 3, stateless, port 8083)&quot;">​</a></h2><h3 id="owns-2" tabindex="-1">Owns <a class="header-anchor" href="#owns-2" aria-label="Permalink to &quot;Owns&quot;">​</a></h3><ul><li><strong>MongoDB — 1 collection</strong>: <code>publish_logs</code> (lịch sử job publish, trạng thái từng lần gọi Social API).</li><li>Không sở hữu bảng nào khác — hoàn toàn stateless ngoài log riêng.</li></ul><h3 id="does-not-own-2" tabindex="-1">Does NOT own <a class="header-anchor" href="#does-not-own-2" aria-label="Permalink to &quot;Does NOT own&quot;">​</a></h3><ul><li>Zero access tới MongoDB business collections hay PostgreSQL của business-service.</li><li>Không tự quyết định publish content nào/khi nào — chỉ nhận job qua RabbitMQ đã được business-service đóng gói đầy đủ (nội dung, media URL, OAuth token đã mã hóa, platform config).</li></ul><h3 id="trach-nhiem-nghiep-vu-chinh-v2-2" tabindex="-1">Trách nhiệm nghiệp vụ chính (V2) <a class="header-anchor" href="#trach-nhiem-nghiep-vu-chinh-v2-2" aria-label="Permalink to &quot;Trách nhiệm nghiệp vụ chính (V2)&quot;">​</a></h3><ul><li>Consume RabbitMQ publish job → gọi đúng Social API (Facebook Post/Story/Reels, Instagram Post/Reels/Story, TikTok Video, Threads Post — UC-87/88/89).</li><li>Retry với backoff (30s → 60s → 120s → DLQ) khi API lỗi.</li><li>Gửi HTTP callback về business-service để cập nhật status Task/Post (<code>PENDING → IN_PROGRESS → DONE/FAIL</code>).</li><li>Third-party Collaborator (báo/banner/TV — không có API) KHÔNG đi qua publisher-service — đó là tracking thủ công trong business-service, xem <code>docs/ba/07-publishing-social-collaborator.md</code> §2.</li></ul><hr><h2 id="_4-nguyen-tac-ranh-gioi-chung" tabindex="-1">4. Nguyên tắc ranh giới chung <a class="header-anchor" href="#_4-nguyen-tac-ranh-gioi-chung" aria-label="Permalink to &quot;4. Nguyên tắc ranh giới chung&quot;">​</a></h2><ol><li><strong>1 DB — 1 owner duy nhất.</strong> Không service nào kết nối trực tiếp vào DB không thuộc sở hữu của mình (xem DA-1154, database ownership diagram, cho chi tiết cross-DB reference strategy).</li><li><strong>business-service là orchestrator nghiệp vụ duy nhất.</strong> ai-service và publisher-service là &quot;worker&quot; thực thi theo lệnh, không tự khởi tạo hành động nghiệp vụ (trừ crawl job theo lịch ADMIN cấu hình).</li><li><strong>RBAC 2 tầng (Agency-level + Workspace-level) chỉ tồn tại trong business-service.</strong> ai-service/publisher-service tin tưởng request đã qua xác thực/phân quyền ở business-service (internal API key, không JWT) — không tự re-check quyền user.</li><li><strong>Third-party Collaborator (báo/banner/TV) là module tracking thủ công trong business-service</strong> — không có service riêng, không tự động hóa như Social API publish.</li></ol>',28)])])}const b=o(s,[["render",c]]);export{u as __pageData,b as default};
